CREATE TABLE el_employee_loan_deductions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,loan_id TEXT NOT NULL,payroll_id TEXT NOT NULL,amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount BETWEEN 1 AND 1000000000),created_by TEXT NOT NULL,created_at INTEGER NOT NULL,applied_journal_id TEXT,UNIQUE(org_id,id),UNIQUE(org_id,loan_id,payroll_id),FOREIGN KEY(org_id,loan_id) REFERENCES el_employee_loans(org_id,id),FOREIGN KEY(org_id,payroll_id) REFERENCES el_staff_payroll(org_id,id),FOREIGN KEY(org_id,created_by) REFERENCES el_memberships(org_id,user_id),FOREIGN KEY(org_id,applied_journal_id) REFERENCES el_journals(org_id,id));
CREATE INDEX el_employee_loan_deduction_loan ON el_employee_loan_deductions(org_id,loan_id,payroll_id);
CREATE INDEX el_employee_loan_deduction_payroll ON el_employee_loan_deductions(org_id,payroll_id);
CREATE TRIGGER el_employee_loan_deduction_insert BEFORE INSERT ON el_employee_loan_deductions BEGIN
 SELECT CASE WHEN NEW.applied_journal_id IS NOT NULL THEN RAISE(ABORT,'Loan deduction must begin reserved') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_employee_loans l JOIN el_staff_payroll p ON p.org_id=l.org_id AND p.employee_id=l.employee_id AND p.branch_id=l.branch_id JOIN el_organizations o ON o.id=l.org_id WHERE l.id=NEW.loan_id AND l.org_id=NEW.org_id AND p.id=NEW.payroll_id AND l.status='disbursed' AND p.status='draft' AND p.total>0 AND l.currency=o.currency AND NEW.amount<=l.principal-COALESCE((SELECT sum(amount) FROM el_employee_loan_recoveries WHERE loan_id=l.id),0)-COALESCE((SELECT sum(amount) FROM el_employee_loan_deductions WHERE loan_id=l.id),0)) THEN RAISE(ABORT,'Employee loan deduction exceeds balance or payroll is unavailable') END;
END;
CREATE TRIGGER el_employee_loan_deduction_update BEFORE UPDATE ON el_employee_loan_deductions BEGIN
 SELECT CASE WHEN NEW.id IS NOT OLD.id OR NEW.org_id IS NOT OLD.org_id OR NEW.loan_id IS NOT OLD.loan_id OR NEW.payroll_id IS NOT OLD.payroll_id OR NEW.amount IS NOT OLD.amount OR NEW.created_by IS NOT OLD.created_by OR NEW.created_at IS NOT OLD.created_at OR OLD.applied_journal_id IS NOT NULL OR NEW.applied_journal_id IS NULL THEN RAISE(ABORT,'Employee loan deduction can only be applied once') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_staff_payroll p JOIN el_employee_loans l ON l.id=NEW.loan_id AND l.org_id=p.org_id JOIN el_journals j ON j.id=NEW.applied_journal_id AND j.org_id=p.org_id WHERE p.id=NEW.payroll_id AND p.org_id=NEW.org_id AND p.status='approved' AND p.accrual_journal_id=NEW.applied_journal_id AND j.status='posted' AND j.branch_id=l.branch_id AND j.source_type='staff_payroll_accrual' AND j.source_id=p.id AND j.date>=l.disbursed_on AND EXISTS(SELECT 1 FROM el_journal_lines x WHERE x.journal_id=j.id AND x.account_id=l.receivable_account_id AND x.credit>=NEW.amount)) THEN RAISE(ABORT,'Employee loan deduction needs the matching posted payroll accrual') END;
END;
CREATE TRIGGER el_employee_loan_deduction_no_delete BEFORE DELETE ON el_employee_loan_deductions BEGIN SELECT RAISE(ABORT,'Employee loan deductions cannot be deleted');END;
DROP TRIGGER el_employee_loan_recovery_guard;
CREATE TRIGGER el_employee_loan_recovery_guard BEFORE INSERT ON el_employee_loan_recoveries BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_employee_loans p WHERE p.id=NEW.loan_id AND p.org_id=NEW.org_id AND p.status='disbursed' AND p.currency=(SELECT currency FROM el_organizations WHERE id=p.org_id) AND NEW.date>=p.disbursed_on AND NEW.amount<=p.principal-COALESCE((SELECT sum(amount) FROM el_employee_loan_recoveries WHERE loan_id=p.id),0)-COALESCE((SELECT sum(amount) FROM el_employee_loan_deductions WHERE loan_id=p.id),0) AND EXISTS(SELECT 1 FROM el_journals j WHERE j.id=NEW.journal_id AND j.org_id=p.org_id AND j.branch_id=p.branch_id AND j.status='posted' AND j.date=NEW.date AND j.source_type='employee_loan_recovery' AND j.source_id=NEW.id AND (SELECT count(*) FROM el_journal_lines WHERE journal_id=j.id)=2 AND EXISTS(SELECT 1 FROM el_journal_lines l WHERE l.journal_id=j.id AND l.account_id=p.receivable_account_id AND l.debit=0 AND l.credit=NEW.amount) AND EXISTS(SELECT 1 FROM el_journal_lines l JOIN el_accounts a ON a.id=l.account_id WHERE l.journal_id=j.id AND a.org_id=p.org_id AND a.system_key=NEW.method AND l.debit=NEW.amount AND l.credit=0))) THEN RAISE(ABORT,'Employee loan recovery exceeds balance or matching journal is unavailable') END;
END;
